-- food menu snapshots, batch 0 (25 menus)
with target as (
  select slug from venues where slug = '12-kitchen-and-wine' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Breakfast Brunch Lunch', 1, 'draft', 'partial', 'https://12kitchenwine.com/wp-content/uploads/2025/12/Breakfast-Brunch-Lunch-Menu_12.pdf', 'Official 12 Kitchen and Wine menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '8974097da65d0fdf41c4527e02147e6d9c8de3033436d0c0c351a33c31e806fb', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('TIMELESS CLASSIC', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('TIMELESS CLASSIC', 'AVO TOAST', 'Sourdough, mash avocado, cherry tomato, feta cheese, poach egg, salad', 105000, 'IDR', 0), ('TIMELESS CLASSIC', 'ADD POACHED EGG', null, 15000, 'IDR', 1), ('TIMELESS CLASSIC', 'ADD CURED SALMON (50GR)', null, 65000, 'IDR', 2), ('TIMELESS CLASSIC', 'CLASSIC CHICKEN SANDWICH', 'Baguette, grilled chicken, avocado, tomato, caesar sauce, romaine', 95000, 'IDR', 3), ('TIMELESS CLASSIC', 'SALMON CROISSANT', 'Croissant, cured salmon, avocado, sunny side up, cream cheese dill, watercress', 140000, 'IDR', 4), ('TIMELESS CLASSIC', 'BEEF CROISSANT', 'Croissant, roasted beef, tomato, caesar sauce, rucola, sun dried tomato, gherkin, cappers, scrambled egg', 125000, 'IDR', 5), ('TIMELESS CLASSIC', 'WHITE OMELETTE TRUFFLE BURRATA', 'Eggs, burrata, truffle paste, slice cucumber', 140000, 'IDR', 6), ('TIMELESS CLASSIC', 'OATMEAL SOURSOP PORRIDGE', 'Oatmeal, sourop jam, berries compote, coconut flake, granola, mix seed', 65000, 'IDR', 7)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

