  select t.slug, 'Brother Gym menu', 1, 'draft', 'partial', 'https://brother-gym-canggu.pages.dev/pricing.html', 'Official Brother Gym menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'be239b37cd56a23a2105bc91b597f80a9f3fc82926745f2cbc8634fccc0cf101', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
