with target as (
  select slug from venues where slug = 'chow-chow-bali' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'cocktails', 1, 'draft', 'partial', 'https://www.chowchowbali.com/s/chowchow-menu.pdf', 'Official Chow Chow Bali menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'e6f0de004274bd136d630c43c9b33220b65acae369e38f71dc7eb778551b35a6', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('beer & SPIKED LEE', 0), ('beer & soda', 1), ('CHOW', 2), ('Bao Buns', 3), ('Crispy Rice Sushi', 4), ('Pomelo Salad', 5), ('POKÉ BOWL • VEGAN', 6), ('sushi', 7), ('larger', 8), ('sides', 9), ('creative roll', 10), ('sweets', 11)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
