join (values ('Traditional Oriental / Full Body', '60 min Canggu', 'Our signature massage. A rejuvenating and stimulating approach to massage. Our unique blend of techniques combines long massage strokes, deep stimulation on muscles and Chinese foot reflexology to leave you feeling entirely rejuvenated.', 323000, 'IDR', 0), ('Traditional Oriental / Full Body', '90 min Canggu', null, 423000, 'IDR', 1), ('Calm and relax me / Full Body', '60 min Canggu', 'A much softer approach with a touch of swedish for those who favour “effleurage” rather than deeper movements. From soft to middle pressure it is all about slow, sliding and long connective movements. Ideal for jet lag and calming the nervous system.', 323000, 'IDR', 0), ('Calm and relax me / Full Body', '90 min Canggu', null, 423000, 'IDR', 1), ('Tension Relief – Deep tissue (optional)', '60 min Canggu', 'Sitting long hours on planes or over a desk, improper posture have inspired these highly beneficial techniques. Our therapists are trained to relieve tension and stress in specific parts of the body. Foot reflexology will also stimulate the body’s recuperative power.', 323000, 'IDR', 0), ('Tension Relief – Deep tissue (optional)', '90 min Canggu', null, 423000, 'IDR', 1), ('Pregnancy Massage / Feel lighter', '60 min Canggu', 'Will make you feel lighter again', 323000, 'IDR', 0), ('Pregnancy Massage / Feel lighter', '90 min Canggu', null, 423000, 'IDR', 1), ('Four hands massage', '60 min Canggu', 'A new signature massage. A marvelous choreography performed by two therapists working in perfect harmony produces an unforgettable journey. Swedish, Lomi-Lomi, Myofascial Stretching, Percussions and Rocking are used in this technique.', 554000, 'IDR', 0), ('Four hands massage', '90 min Canggu', null, 715000, 'IDR', 1), ('Warm Stones Massage', '90 min Canggu', 'Basaltic warm stones ensure a deeper relaxation and purification. Experience the healing powers of this age-old detoxifying therapy.', 519000, 'IDR', 0), ('Crystal aromatheraphy foot reflexology', '60 min Canggu', 'Discover the benefits of this relaxing as well as tonifying and stimulating approach. It is ideal for jet lag. Acupressure, deep strokes and drainage will make your feet and full body feel entirely new.', 299000, 'IDR', 0), ('Crystal aromatheraphy foot reflexology', '90 min Canggu', null, 387000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

