join (values ('Promotional Packages', 'Rayakan Hari Kemerdekaan Indonesia dengan paket canape premium eksklusif kami', 'Paket free-flow bekelas berdurasi satu jam yang dirancang untuk acara social dengan sajian cocktail maupun kegiatan mixology perusahaan', 117000, 'IDR', 0), ('Promotional Packages', 'Regal Javanese Heritage', 'Sederatn pennyajian hindangan yang elegan dan berkelas,mengakat resep resep instana kerajaan.', 300000, 'IDR', 1), ('Promotional Packages', 'Balinese Rijsttafel', 'An immersive, grand feast format reflecting genueine communal luxury.', 450000, 'IDR', 2), ('Promotional Packages', 'Let''s Just Celebrate Indonesia''s Independence with us', 'Suitable for 8 person - included a dedicated private chef on-site.', 1780000, 'IDR', 3)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

update menus set status = 'source_snapshot', source_snapshot_published_at = '2026-08-25T01:47:06+00:00'::timestamptz
where status = 'draft'
  and completeness = 'partial'
  and verified_at is null
  and content_digest is not null
  and expires_at > now()
  and created_at >= '2026-08-25T01:47:06+00:00'::timestamptz
  and exists (select 1 from menu_sections s join menu_items it
              on it.section_id = s.id and it.menu_id = s.menu_id
              where s.menu_id = menus.id);
